  'Design History surveys the development of graphic design and visual communication from early writing and print culture through industrial production, reform movements, modernism, Swiss style, corporate identity, postmodernism, digital media, global design histories, contemporary platforms, and ethical design practice. Students learn to analyze artifacts, read visual form historically, question design canons, use archives and museum collections, and write critical design-history arguments.',
  $dhisjson${"slug": "design-history", "title": "Design History", "description": "Design History surveys the development of graphic design and visual communication from early writing and print culture through industrial production, reform movements, modernism, Swiss style, corporate identity, postmodernism, digital media, global design histories, contemporary platforms, and ethical design practice. Students learn to analyze artifacts, read visual form historically, question design canons, use archives and museum collections, and write critical design-history arguments.", "topics": [{"id": "b749db31-89b8-4389-9525-5aedc705fa44", "type": "topic", "title": "Design History as Visual Culture and Method", "description": "This opening unit frames design history as the study of visual communication, technology, labor, markets, institutions, and culture rather than a simple parade of styles.", "children": [{"id": "a78be4ae-3807-4720-bf51-56801d88d836", "type": "subtopic", "title": "What counts as design history", "children": [{"id": "1e15bbc3-a4de-4171-8d23-ddf1176ef179", "type": "concept", "title": "artifact"}, {"id": "b542474e-7f4d-4411-9200-54c4e2a5297b", "type": "concept", "title": "visual culture"}, {"id": "09fab5bf-8758-45e7-b55c-955a031302dc", "type": "concept", "title": "graphic design"}, {"id": "caf6cf3d-a62b-4cbd-9428-18b8a76b3821", "type": "concept", "title": "communication design"}, {"id": "31865fa9-cb80-46af-947d-540535998791", "type": "concept", "title": "vernacular design"}, {"id": "496274d5-721a-4882-93f6-3b2c2b0d45e3", "type": "concept", "title": "material culture"}], "description": "Students learn how posters, books, signs, interfaces, packaging, typefaces, corporate identity, and vernacular graphics become historical evidence."}, {"id": "96cae6ac-d0f1-412b-9a2e-be8691a51374", "type": "subtopic", "title": "Methods of visual analysis", "children": [{"id": "aca408a1-8209-45cc-bfb4-c2838ae5349e", "type": "concept", "title": "formal analysis"}, {"id": "34a09fd3-aca3-4ad6-9194-b14a0ae6916d", "type": "concept", "title": "iconography"}, {"id": "ed8e1982-ce1c-40e4-bbca-482609c72627", "type": "concept", "title": "composition"}, {"id": "dec4dafe-9104-4e51-afa9-c59bacbc5c3a", "type": "concept", "title": "typographic analysis"}, {"id": "e7c89e99-fa10-448b-93f7-acfe9c2dd1f4", "type": "concept", "title": "semiotics"}, {"id": "43aae45e-b0e7-451b-9f51-ca0c0179397b", "type": "concept", "title": "contextual reading"}], "description": "This subtopic introduces close looking and historical interpretation so students can connect form to context."}, {"id": "02c1a806-d1b3-495a-81a4-d6359d7bcaab", "type": "subtopic", "title": "Canons, archives, and missing histories", "children": [{"id": "f96fc276-89ac-4e77-b287-c3e00ed14a4c", "type": "concept", "title": "canon formation"}, {"id": "85036372-6dc9-4ca8-9a1a-ee7059d47716", "type": "concept", "title": "archive bias"}, {"id": "f35dbe13-841d-4281-9f26-c86252d4cf1a", "type": "concept", "title": "anonymous labor"}, {"id": "57abe375-835a-4be4-90ce-f2700566adb5", "type": "concept", "title": "women designers"}, {"id": "3b3a9309-7e41-4d8c-bf95-8f906476154d", "type": "concept", "title": "racial exclusion"}, {"id": "24f136f1-e8e8-451f-be64-389d2eb84972", "type": "concept", "title": "decolonial method"}], "description": "Students question whose work is preserved, taught, collected, and excluded from dominant design-history narratives."}]}, {"id": "68b57b31-4abf-4b2f-ab1a-c36d15017e7b", "type": "topic", "title": "Origins of Graphic Communication and Early Print", "description": "This unit studies the long prehistory of graphic design, from writing systems and manuscripts to movable type and early print culture.", "children": [{"id": "a7e84fc2-d4fc-4fe2-9e17-557b8d98d30d", "type": "subtopic", "title": "Writing systems and manuscript cultures", "children": [{"id": "7738bec0-d2c0-47cc-8954-360b0f2774a7", "type": "concept", "title": "cuneiform"}, {"id": "dbb56975-ed44-4d22-b14c-f527a88b99ef", "type": "concept", "title": "hieroglyphics"}, {"id": "e73c194c-6bad-42b4-a89e-cbdd4d5123ff", "type": "concept", "title": "calligraphy"}, {"id": "470ec618-c841-4a67-91fe-1fb1b46c1fb9", "type": "concept", "title": "illuminated manuscript"}, {"id": "5647a282-737d-4081-ab8c-a89cab65f7f2", "type": "concept", "title": "scribal labor"}, {"id": "79c13f31-86fa-4c70-89ef-d0e23aada4f7", "type": "concept", "title": "page architecture"}], "description": "Students trace how visual communication emerged through scripts, symbols, religious texts, and administrative records."}, {"id": "e232e3d3-f4f0-45dc-801c-3887ae9166b2", "type": "subtopic", "title": "Movable type and print revolution", "children": [{"id": "a937e349-963a-4cdb-95fa-eed8897178ce", "type": "concept", "title": "Gutenberg"}, {"id": "04c6be5e-0ef4-418e-96c7-4f857b1ebcbf", "type": "concept", "title": "movable type"}, {"id": "904d2512-fb1f-495f-ade9-867c26f14dd3", "type": "concept", "title": "incunabula"}, {"id": "dd724741-61d3-4689-b01d-9e6057790a41", "type": "concept", "title": "woodcut"}, {"id": "2e538487-cf7f-4c61-b974-3662f00aa298", "type": "concept", "title": "engraving"}, {"id": "c3c80c75-8f18-489e-9435-a82c53dd2a5f", "type": "concept", "title": "printer-publisher"}], "description": "This subtopic explains how print changed reproduction, authorship, standardization, literacy, and public communication."}, {"id": "3dba2021-b4d6-4a9e-b5e1-de487ea68e40", "type": "subtopic", "title": "Early type and book design", "children": [{"id": "4ae1be16-d19b-41df-9a54-735955953515", "type": "concept", "title": "roman type"}, {"id": "e580156d-c259-4c10-9d2f-fa31615bfac9", "type": "concept", "title": "blackletter"}, {"id": "de3d3cf3-2d97-40fb-a0be-80972d19810c", "type": "concept", "title": "humanist type"}, {"id": "b07a8d2f-7c33-4392-a5b8-4fc84db66d37", "type": "concept", "title": "title page"}, {"id": "6ea72b9e-26f9-47eb-b937-7ee265ba5787", "type": "concept", "title": "margins"}, {"id": "0c68a9e1-66c4-4b07-bfda-10a92b9e8c74", "type": "concept", "title": "colophon"}], "description": "Students learn the historical roots of type classification, page proportion, ornament, and reader experience."}]}, {"id": "dba41f25-3aa1-4423-ace9-a6135ddeef95", "type": "topic", "title": "Industrial Revolution, Mass Media, and Advertising", "description": "Industrialization transformed design through mechanized printing, mass audiences, urban posters, packaging, newspapers, and consumer culture.", "children": [{"id": "70b67330-7e78-4c8c-a5ca-8cbbef7b259b", "type": "subtopic", "title": "Mechanized printing and reproduction", "children": [{"id": "cb480251-8ca0-4b3c-9d1f-82a4d716f8cf", "type": "concept", "title": "lithography"}, {"id": "e183b138-5759-44d3-898e-1d3332240198", "type": "concept", "title": "chromolithography"}, {"id": "7ac8d966-4305-4de1-8fc3-dae363f855f5", "type": "concept", "title": "steam press"}, {"id": "f2ee21d5-1b16-4e64-9784-41a5a88d5095", "type": "concept", "title": "halftone"}, {"id": "6234e3ee-7a91-43dc-b817-642eb6f4d22c", "type": "concept", "title": "typefoundry"}, {"id": "8a25ccf1-36e5-4ba8-81d7-29310cda0afe", "type": "concept", "title": "mechanical reproduction"}], "description": "Students connect new technologies to faster production, larger editions, color printing, and changing design labor."}, {"id": "35ce2585-7a86-4388-8a4a-0c595049d5bf", "type": "subtopic", "title": "Advertising and consumer culture", "children": [{"id": "ed1c2ce8-c84a-4fce-b538-83a78ff4a4b0", "type": "concept", "title": "display type"}, {"id": "5565d33a-35a7-409f-829c-d4e12b62b8f1", "type": "concept", "title": "trade card"}, {"id": "6988ac3c-98bc-42c1-b612-ab32d49db16f", "type": "concept", "title": "poster culture"}, {"id": "27cd49bc-10fa-4e12-bbc2-cb407f7cde83", "type": "concept", "title": "packaging"}, {"id": "99906f91-f4c5-436c-a734-0b92dafc99df", "type": "concept", "title": "brand mark"}, {"id": "dae7aa74-3207-4e76-bd83-ce5dce184ef7", "type": "concept", "title": "department store"}], "description": "This subtopic examines how brands, posters, catalogs, and packaging reshaped public space and desire."}, {"id": "1536ab16-b235-4c2b-a280-4cbfc0b3bd02", "type": "subtopic", "title": "Information, newspapers, and public graphics", "children": [{"id": "108bb9a2-89cd-4e1d-9d77-c1390cbf7b2b", "type": "concept", "title": "newspaper layout"}, {"id": "467f7c1c-eae1-435b-ba93-90577e74d31a", "type": "concept", "title": "headline hierarchy"}, {"id": "2445a16f-646a-4fe5-bdc5-1b978af8c907", "type": "concept", "title": "caption"}, {"id": "67caf09d-2af5-4b0f-96a7-754b1441d6eb", "type": "concept", "title": "infographic precursor"}, {"id": "83a27754-06b4-4732-b7b5-c242f2e9eb83", "type": "concept", "title": "public notice"}, {"id": "08247ca2-92b0-42f0-b8e5-67c0c8624cfb", "type": "concept", "title": "railway timetable"}], "description": "Students study how mass media required hierarchy, grids, illustration, captions, and repeatable editorial systems."}]}, {"id": "ba37750c-a09c-42a7-a1f0-c311262c21d5", "type": "topic", "title": "Arts and Crafts, Art Nouveau, and Design Reform", "description": "This unit examines late nineteenth-century responses to industrial production, including craft revival, aesthetic reform, and organic graphic styles.", "children": [{"id": "9ad2b922-4c0f-42e4-8ccb-dbb61c6f3f19", "type": "subtopic", "title": "Arts and Crafts movement", "children": [{"id": "77c6f5a2-c9d9-4056-bbe6-4960093db2e5", "type": "concept", "title": "William Morris"}, {"id": "d3f9351a-de5a-447a-bfa9-e5d84924bbd0", "type": "concept", "title": "Kelmscott Press"}, {"id": "04f1904d-0aa5-452e-8e68-a07aa199b08f", "type": "concept", "title": "craft revival"}, {"id": "7d1bbef7-c010-4b79-af93-5cc2161d88af", "type": "concept", "title": "ornament"}, {"id": "8a0ed53b-e5fd-4ff3-9292-48d077fc55c9", "type": "concept", "title": "medievalism"}, {"id": "5f7711b3-ee7b-472e-ae94-d43f9a43ff00", "type": "concept", "title": "anti-industrial critique"}], "description": "Students learn how William Morris and related reformers linked design quality to labor, morality, and industrial critique."}, {"id": "b0bc8485-a6f3-429f-9329-e5181d2b79f7", "type": "subtopic", "title": "Art Nouveau and the modern poster", "children": [{"id": "cfc0b51c-2e90-4c15-b825-74874f1bf0b8", "type": "concept", "title": "Jules Cheret"}, {"id": "4e7c6d9f-5e01-4848-8482-adf5a5f123db", "type": "concept", "title": "Alphonse Mucha"}, {"id": "24f5df8b-b5c0-4fa9-98bd-71a8eccff0bd", "type": "concept", "title": "Henri de Toulouse-Lautrec"}, {"id": "3d76effb-6e27-44d4-a935-c213559f7416", "type": "concept", "title": "flat color"}, {"id": "cae8ff3c-6623-4cd0-bd8c-4acb5bfb668a", "type": "concept", "title": "whiplash line"}, {"id": "8086dec6-a422-4eb3-b3c5-d6eb8a74f6d9", "type": "concept", "title": "lithographic poster"}], "description": "This subtopic studies flowing line, flat color, sensual ornament, and the rise of designer-authored posters."}, {"id": "8cae468d-e8d6-4fa6-9651-0009bbe7bf8e", "type": "subtopic", "title": "Design reform and applied arts", "children": [{"id": "6e21bacb-a699-4050-b06e-4390e8ab85c8", "type": "concept", "title": "design reform"}, {"id": "e26ff375-8277-4a96-a1fa-345733183de3", "type": "concept", "title": "applied arts"}, {"id": "3074ae8b-ffe5-48d2-8afc-7fee625b707d", "type": "concept", "title": "Werkbund"}, {"id": "45c61531-6ab6-43fa-947d-9feb1e22b8af", "type": "concept", "title": "ornament debate"}, {"id": "c7863019-040a-40a9-9bca-8e0cb3d620a0", "type": "concept", "title": "total work of art"}, {"id": "1a9d22b4-2cfd-41c0-abb1-10cf6a8eff1d", "type": "concept", "title": "craft versus industry"}], "description": "Students connect reform movements to education, craft guilds, exhibitions, and the later emergence of modern design schools."}]}, {"id": "1938c190-befd-40c6-9ffd-b7cce601400c", "type": "topic", "title": "Modernism: Futurism, Constructivism, De Stijl, and Bauhaus", "description": "Modernist design sought new visual languages for industrial society, abstraction, political transformation, and universal communication.", "children": [{"id": "da27aab9-791c-437a-a987-e6542ca4ecc0", "type": "subtopic", "title": "Avant-garde typography and montage", "children": [{"id": "52ca6178-60f7-4acc-a1fe-a73eaa4a20f5", "type": "concept", "title": "Futurism"}, {"id": "25bca5f2-3889-4158-86fb-c3e61d8e8804", "type": "concept", "title": "Dada"}, {"id": "ec7b4983-4310-4472-aeeb-5df832bbc07c", "type": "concept", "title": "photomontage"}, {"id": "e53f2a20-45ab-4f76-8d99-0f816bad1e54", "type": "concept", "title": "asymmetry"}, {"id": "d67f642e-1f0f-4e4c-bf56-82c6736ec2cc", "type": "concept", "title": "dynamic typography"}, {"id": "6ac2ecbb-2192-4a50-9965-1d6f5dcf288d", "type": "concept", "title": "El Lissitzky"}], "description": "Students study how Futurists, Dadaists, and Constructivists broke classical page order to express speed, rupture, and politics."}, {"id": "aaefccdb-07ca-4a61-9079-e42c344538a8", "type": "subtopic", "title": "De Stijl and geometric abstraction", "children": [{"id": "b70e9926-a3bf-463b-ab85-b565e7d6dd39", "type": "concept", "title": "De Stijl"}, {"id": "00006097-ea5c-4458-a721-62554c068480", "type": "concept", "title": "Piet Mondrian"}, {"id": "4d557466-8b7c-4a1a-8e4b-813d32888252", "type": "concept", "title": "Theo van Doesburg"}, {"id": "03e38310-36b1-4435-84ec-d1acdb0834a3", "type": "concept", "title": "grid"}, {"id": "d8b55c86-9e65-4413-b40c-08ad5dbe9e76", "type": "concept", "title": "primary color"}, {"id": "03b83971-5bb9-446c-95dd-0cd65153b794", "type": "concept", "title": "geometric reduction"}], "description": "This subtopic explores reduction, grids, primary colors, and the search for universal visual order."}, {"id": "dabba2be-9e69-4345-bcea-57020059293c", "type": "subtopic", "title": "Bauhaus pedagogy and modern design education", "children": [{"id": "be36b563-6f42-4cdc-aecc-54c0665cd7ef", "type": "concept", "title": "Bauhaus"}, {"id": "47302437-0576-4af5-a03a-87476157ec91", "type": "concept", "title": "Vorkurs"}, {"id": "0adae1ee-5265-48d4-8531-eced2bc5b145", "type": "concept", "title": "Herbert Bayer"}, {"id": "4c9e3dfc-e6ce-4c53-91c4-d3ec6e082518", "type": "concept", "title": "László Moholy-Nagy"}, {"id": "dde44e51-9e58-490f-bf6e-1b1dd855ec68", "type": "concept", "title": "workshop model"}, {"id": "a1480349-406a-49a0-9bc7-6157ec43393e", "type": "concept", "title": "form follows function"}], "description": "Students learn how the Bauhaus linked foundation studies, workshop practice, typography, industry, and design theory."}]}, {"id": "53e6ccdf-87ec-4acd-9ff6-0f10bdd71792", "type": "topic", "title": "Swiss International Style and Corporate Modernism", "description": "This unit covers rational grids, sans serif typography, objectivity, and the postwar corporate identity systems that shaped twentieth-century visual communication.", "children": [{"id": "cd61bc06-16d5-4b9b-b81a-c1f1bb3ce244", "type": "subtopic", "title": "International Typographic Style", "children": [{"id": "3b9d0422-0803-4946-a613-08428f81bb26", "type": "concept", "title": "Josef Muller-Brockmann"}, {"id": "7d37ae50-7101-4090-a24c-b05908bb5c75", "type": "concept", "title": "Armin Hofmann"}, {"id": "6fb73182-9b68-4136-8fe4-9bf74da615a3", "type": "concept", "title": "grid system"}, {"id": "8c2ba8e4-b196-4950-9837-023c2d22cddb", "type": "concept", "title": "asymmetrical layout"}, {"id": "95bb412c-da51-42a4-8838-27cad1b28d02", "type": "concept", "title": "Akzidenz-Grotesk"}, {"id": "dc4a1175-fd2b-40f9-a072-fdc63b49022a", "type": "concept", "title": "photographic objectivity"}], "description": "Students learn the formal language of Swiss design and its promise of clarity, neutrality, and systematic order."}, {"id": "f044e144-dbd3-4616-bfa4-bf2171931d90", "type": "subtopic", "title": "Corporate identity systems", "children": [{"id": "7d5d793e-01a8-4ccd-ac7b-10db79f52346", "type": "concept", "title": "Paul Rand"}, {"id": "30027e7b-0765-48fb-b2cd-a72cc7d03343", "type": "concept", "title": "Chermayeff & Geismar"}, {"id": "6d77887d-2076-46c9-98e5-f9a3b74c1d13", "type": "concept", "title": "identity manual"}, {"id": "2458508c-d567-4dde-98ec-39236b63b4e2", "type": "concept", "title": "logo"}, {"id": "942ad94f-8ae1-4f8f-887c-69025bc7f465", "type": "concept", "title": "system standards"}, {"id": "88b7fa04-41c0-48d4-8f75-3d4fd713bb5f", "type": "concept", "title": "brand consistency"}], "description": "This subtopic studies how institutions used marks, manuals, color, type, and repeatable standards to manage public presence."}, {"id": "73a172d6-0be6-4e92-8de9-700f089ce94c", "type": "subtopic", "title": "Critiques of neutrality", "children": [{"id": "66f73613-b548-40b1-b8cb-d422c5dbbf1e", "type": "concept", "title": "neutrality myth"}, {"id": "e74a8b52-dd55-40bd-92d2-75408260fb20", "type": "concept", "title": "corporate voice"}, {"id": "bfa1dd44-ba6a-4bd7-b333-5d695665aedf", "type": "concept", "title": "institutional authority"}, {"id": "4d8c63dc-e20b-4ac2-9125-bcec5cb15eea", "type": "concept", "title": "legibility politics"}, {"id": "8ab6313f-87dc-4355-ac77-f14d15bfdd36", "type": "concept", "title": "modernist exclusion"}, {"id": "9062d9b6-f724-4bb3-ad5e-5c49567cd78c", "type": "concept", "title": "global export"}], "description": "Students question whether modernist clarity is ever culturally neutral and examine how power can hide inside universal style."}]}, {"id": "87c873c3-0fc5-46b0-9c81-48f29d19de96", "type": "topic", "title": "Typography, Letterforms, and Publication Histories", "description": "Typography has its own histories of tools, technologies, classification, distribution, and cultural meaning. This unit makes type central to design history.", "children": [{"id": "b6e20a01-5f8e-427a-8bc1-6a02b02fd6f6", "type": "subtopic", "title": "Type classification and historical form", "children": [{"id": "b104e2e1-99b2-498c-b6e6-7f4b148fae11", "type": "concept", "title": "old style"}, {"id": "d4c63a52-ae48-49b7-9a92-5567888c6fab", "type": "concept", "title": "transitional"}, {"id": "e9b02448-5cb0-4703-bb84-5594a290e4cd", "type": "concept", "title": "modern"}, {"id": "2a921fd8-f42e-4c95-823d-13059e982b7d", "type": "concept", "title": "slab serif"}, {"id": "aa3da45d-69c6-44a9-ae52-3d8c507b36d1", "type": "concept", "title": "grotesque"}, {"id": "6718df2f-5f74-460b-814e-4b7dc570880c", "type": "concept", "title": "humanist sans"}], "description": "Students learn how typefaces carry traces of tools, periods, and reading technologies."}, {"id": "327d8240-43b4-4eaf-827f-7a04c8c1660a", "type": "subtopic", "title": "Letterpress, phototype, and digital type", "children": [{"id": "4d4bc912-8454-42a9-a4cc-e35af3af5643", "type": "concept", "title": "letterpress"}, {"id": "71001466-df99-4a96-9238-fe10f4a585dd", "type": "concept", "title": "Linotype"}, {"id": "fdb1b566-5cc5-4153-846a-81889d3e6bde", "type": "concept", "title": "Monotype"}, {"id": "628779a9-cc6e-407c-be55-6e647d3d310d", "type": "concept", "title": "phototypesetting"}, {"id": "67b731e6-611e-47a2-92da-d83cb77a32bc", "type": "concept", "title": "PostScript"}, {"id": "8966d286-0d34-4305-847b-337d05e605d8", "type": "concept", "title": "OpenType"}], "description": "This subtopic follows changes in production from metal type to phototypesetting to font software."}, {"id": "f96163e7-2d10-4d8d-93c6-767f5ea9220d", "type": "subtopic", "title": "Typographic culture and archives", "children": [{"id": "4fa7faf7-8a7e-45a2-b877-2f7acf9dc591", "type": "concept", "title": "type specimen"}, {"id": "f6b19075-8454-4d14-a341-fbe3f244799b", "type": "concept", "title": "foundry"}, {"id": "d8ea6d61-8b31-427f-8e76-462e6ff23bb1", "type": "concept", "title": "revival"}, {"id": "ce46b9e2-32e7-4e2d-82e5-44318418284c", "type": "concept", "title": "Letterform Archive"}, {"id": "7d2050c2-a9ed-4bf0-bf1b-e1e0ff253e39", "type": "concept", "title": "vernacular lettering"}, {"id": "36b7e662-b8b4-4438-8d5e-0f3a8bf882ce", "type": "concept", "title": "font licensing"}], "description": "Students study specimens, foundry histories, revivals, and letterform collections as evidence."}]}, {"id": "b5bbd016-fc5d-482f-9365-e39e5b544fab", "type": "topic", "title": "Identity, Branding, and Design Systems in History", "description": "Branding has a long history that connects marks, commerce, institutions, standardization, and public trust.", "children": [{"id": "83825466-179b-438c-b25f-5ad2dfa73d1f", "type": "subtopic", "title": "Marks, symbols, and trademarks", "children": [{"id": "1ffff46d-6b55-44b4-910c-a7916c870ca9", "type": "concept", "title": "maker mark"}, {"id": "73529f91-730e-4e01-b339-a20864487e3c", "type": "concept", "title": "trademark"}, {"id": "3caedc9a-f550-4297-9c75-4890a0c25cd1", "type": "concept", "title": "symbol"}, {"id": "126f337b-767f-4bc8-bfdb-689106b39698", "type": "concept", "title": "monogram"}, {"id": "8c0a381e-f442-4d98-bb92-2938a8304b99", "type": "concept", "title": "seal"}, {"id": "a3fb52f4-a542-49c3-9cad-2e23de47921f", "type": "concept", "title": "brand recognition"}], "description": "Students connect early maker marks and trademarks to modern logo systems and intellectual property."}, {"id": "cca3924e-ca17-4587-8627-cca8b4e5d484", "type": "subtopic", "title": "System design and standards", "children": [{"id": "b6f07db7-8de3-49aa-8823-08cf7c9dcc31", "type": "concept", "title": "standards manual"}, {"id": "59b8d8d0-d3d9-4863-acf8-514d5b242e1e", "type": "concept", "title": "visual identity"}, {"id": "3ffb2bb7-12b2-47f5-9657-e06c2f5a70ec", "type": "concept", "title": "wayfinding"}, {"id": "5a5f06f6-cc91-4ef1-a9a4-e9a1b063056e", "type": "concept", "title": "supergraphics"}, {"id": "27017911-6cef-457e-8d84-11f85e992614", "type": "concept", "title": "application system"}, {"id": "fbdedaf1-b891-44b3-8051-a1ed72da61b9", "type": "concept", "title": "design guidelines"}], "description": "This subtopic examines how identity systems coordinate type, color, layout, imagery, signage, and applications."}, {"id": "7ba1ef65-e966-4b9c-b547-fb7aceb99a43", "type": "subtopic", "title": "Branding as cultural narrative", "children": [{"id": "a5a4c4f7-8631-4379-8cbc-bd31995b5b98", "type": "concept", "title": "brand narrative"}, {"id": "0360ac91-f3d5-489b-bddc-fc57b07b71ec", "type": "concept", "title": "consumer identity"}, {"id": "b192ea0b-3184-473c-9c34-0dbf880e52e5", "type": "concept", "title": "corporate citizenship"}, {"id": "6498191f-017c-4f16-997b-e8239a235f31", "type": "concept", "title": "nation branding"}, {"id": "f279e95e-4472-4992-ae47-d0ed064c297b", "type": "concept", "title": "lifestyle branding"}, {"id": "bfa0ce79-cc8c-4d19-a700-867340031910", "type": "concept", "title": "visual persuasion"}], "description": "Students analyze how brands tell stories about modernity, lifestyle, nation, technology, or social values."}]}, {"id": "e40cece8-ef36-4bcb-bdeb-60877afb4fd9", "type": "topic", "title": "Postmodernism, New Wave, and Critical Graphic Design", "description": "Postmodern design challenged modernist order through quotation, fragmentation, vernacular references, expressive typography, and critical authorship.", "children": [{"id": "7b26eccd-4c2b-4d13-a90e-d28484c37995", "type": "subtopic", "title": "New Wave and expressive typography", "children": [{"id": "5a983aa6-e36d-453d-8435-4f7e40a4fbbb", "type": "concept", "title": "Wolfgang Weingart"}, {"id": "11c387eb-df26-41ac-af09-30633a542f26", "type": "concept", "title": "April Greiman"}, {"id": "2f956f5b-89cd-4e3a-aebb-8839df92c4de", "type": "concept", "title": "Emigre"}, {"id": "fde43f16-a5d3-4964-9ffa-5f42e5cea176", "type": "concept", "title": "layering"}, {"id": "3f27a511-6284-4263-9b1e-4e16007c9c35", "type": "concept", "title": "pixel typography"}, {"id": "fa469c1f-8211-4698-9a6d-4313dcbcc403", "type": "concept", "title": "typographic expression"}], "description": "Students study designers who used type as image, voice, rhythm, and instability."}, {"id": "70f8c8c1-7f4a-414e-a1d6-7e0b42b7f802", "type": "subtopic", "title": "Postmodern quotation and vernacular form", "children": [{"id": "dd2e2cd3-7fc9-434e-a6a3-6b8a5926bad4", "type": "concept", "title": "pastiche"}, {"id": "01a282b4-415b-4624-b925-42ff0b2a33c5", "type": "concept", "title": "vernacular"}, {"id": "4d021649-5a11-4003-9d72-c8acb68d76b0", "type": "concept", "title": "retro"}, {"id": "8b59aa38-1cd2-43e1-a40e-92c328cc2edc", "type": "concept", "title": "Memphis"}, {"id": "03d47a3c-717e-4b11-89aa-5d436336066a", "type": "concept", "title": "ornament return"}, {"id": "9a4f2c7c-e760-428e-8726-f03e42dec8e9", "type": "concept", "title": "historical quotation"}], "description": "This subtopic examines historical references, irony, ornament, pastiche, and anti-neutral design languages."}, {"id": "b1c231ad-5f50-46a7-b925-b4fdb8adaa0b", "type": "subtopic", "title": "Design authorship and critique", "children": [{"id": "71f0fe86-1650-4947-957f-351b0e9a4a10", "type": "concept", "title": "designer as author"}, {"id": "4c883e5b-9392-476b-bccc-49592ea9c1f7", "type": "concept", "title": "critical design"}, {"id": "76de1d3f-96b9-43c1-a733-695be82d390f", "type": "concept", "title": "authorship"}, {"id": "0d7a31c2-9075-4128-af7e-9ab256d05de3", "type": "concept", "title": "deconstruction"}, {"id": "970989f0-358f-4eac-ac14-1ab76245e6fb", "type": "concept", "title": "visual essay"}, {"id": "e417d467-636a-468c-9883-8e96ed8e040f", "type": "concept", "title": "self-reflexivity"}], "description": "Students explore designer-as-author debates and design as commentary, research, and cultural criticism."}]}, {"id": "4baa3833-ab8b-4be2-8b51-04c4e95c69ce", "type": "topic", "title": "Digital Revolution and Networked Design", "description": "Digital tools reshaped design production, distribution, typography, image-making, interactivity, and the designer's role.", "children": [{"id": "cbdd6db3-75c7-4780-b5ca-e7cee38cec40", "type": "subtopic", "title": "Desktop publishing and software cultures", "children": [{"id": "3c9dd521-84f7-49e6-9645-ab474cc940da", "type": "concept", "title": "Macintosh"}, {"id": "5adc91b4-6cfc-441f-99c9-c5d8f389fc24", "type": "concept", "title": "desktop publishing"}, {"id": "3cbbdae7-cda4-4f74-adc1-7540e72c56b5", "type": "concept", "title": "PageMaker"}, {"id": "86eba3fc-8852-4166-b696-4a485644435c", "type": "concept", "title": "QuarkXPress"}, {"id": "4862060a-92ef-40d0-a418-e35ce73ee215", "type": "concept", "title": "Photoshop"}, {"id": "8d3979b0-bebb-49f4-9531-b6918fa378c6", "type": "concept", "title": "digital prepress"}], "description": "Students learn how personal computers, page-layout software, and digital type changed who could make and distribute design."}, {"id": "e6597421-7e72-456f-b855-c76203f33bf5", "type": "subtopic", "title": "Web and interface histories", "children": [{"id": "0d689c38-6b23-4a95-8a3f-fffb3260a927", "type": "concept", "title": "HTML"}, {"id": "4e2235fa-78a5-4449-bccd-5d227bbbfe55", "type": "concept", "title": "browser"}, {"id": "2446ae64-1055-44f4-8e95-5a6040c2cb12", "type": "concept", "title": "GUI"}, {"id": "bf7209c9-1a56-4fe3-86e7-cc405d2b15d6", "type": "concept", "title": "pixel grid"}, {"id": "2642fe50-df95-4bf3-931e-8515d8841e66", "type": "concept", "title": "responsive design"}, {"id": "c4fa6e05-8dc4-4ff0-bdeb-7db25c9dc716", "type": "concept", "title": "interaction pattern"}], "description": "This subtopic connects graphic design to early websites, screens, interaction patterns, and interface standards."}, {"id": "07295c04-3d46-4254-9992-67fde8776d2b", "type": "subtopic", "title": "Platforms, templates, and automation", "children": [{"id": "1212d038-a33b-4a3c-8596-9de6abcd53b8", "type": "concept", "title": "template culture"}, {"id": "f5fd2192-4c16-4eb3-91dc-6e0d7f36948c", "type": "concept", "title": "social media graphics"}, {"id": "b5a2cb4b-10af-419b-855f-f29cf9e01184", "type": "concept", "title": "platform constraint"}, {"id": "c695f89b-5f3c-4abf-8b7b-576210e3885a", "type": "concept", "title": "algorithmic feed"}, {"id": "ce4cdbcb-bd0b-4993-89b3-3e5fc9fa02ae", "type": "concept", "title": "design system"}, {"id": "a4df12cc-10d7-4f9d-8397-9921d1bfba84", "type": "concept", "title": "generative tool"}], "description": "Students analyze contemporary design production through templates, social media systems, no-code tools, and algorithmic distribution."}]}, {"id": "2c07f430-0e71-49ca-adcd-4d5ee13179fd", "type": "topic", "title": "Global and Decolonial Design Histories", "description": "Design history must move beyond a narrow Euro-American canon and study design across regions, languages, scripts, colonial histories, and local visual systems.", "children": [{"id": "2aae5d8e-757e-4fa4-9c7a-f100f0114fc3", "type": "subtopic", "title": "Non-Western modernisms", "children": [{"id": "1f6bf009-0c08-4473-b2da-4065da383397", "type": "concept", "title": "Latin American modernism"}, {"id": "007f79bb-2934-43e2-a75d-1c71e4331f31", "type": "concept", "title": "Japanese graphic design"}, {"id": "e10ebefe-1b5f-4633-b171-d9c144be6f31", "type": "concept", "title": "Indian print culture"}, {"id": "5aa778f1-fe3e-447c-9d32-230756a9e2ed", "type": "concept", "title": "African poster traditions"}, {"id": "0e213406-40bf-4d39-87e3-d28eb2a4e026", "type": "concept", "title": "Arabic typography"}, {"id": "6eff128b-5758-44cf-bdca-921ed65a30d9", "type": "concept", "title": "postcolonial modernity"}], "description": "Students examine modern design in Latin America, East Asia, South Asia, Africa, and the Middle East on its own terms."}, {"id": "78f7d1f4-0123-46e9-979d-8b98c27ba053", "type": "subtopic", "title": "Colonialism, nationalism, and design", "children": [{"id": "758f6725-cde1-4aac-9de4-e7829d1d926f", "type": "concept", "title": "colonial exhibition"}, {"id": "6db179e7-c3fa-4d28-9d77-d495e1b47917", "type": "concept", "title": "propaganda"}, {"id": "3326e64c-7df4-46be-a5d6-d48853f34691", "type": "concept", "title": "national identity"}, {"id": "0cf62d80-b60a-4029-bbfe-9f123c884d60", "type": "concept", "title": "anti-colonial graphics"}, {"id": "c4724bb7-5050-47f5-80e1-78c68061ab8e", "type": "concept", "title": "public information"}, {"id": "6eefff8e-bd5b-40f1-98e2-4c89734fd85a", "type": "concept", "title": "state design"}], "description": "This subtopic connects design to empire, independence movements, public campaigns, and national identity."}, {"id": "c92e47e9-08b9-4d91-94ff-bba4430bebff", "type": "subtopic", "title": "Translation, script, and locality", "children": [{"id": "6881c469-0726-4984-b3e2-98f54991a9bf", "type": "concept", "title": "multiscript typography"}, {"id": "805da5c4-9b2e-45d8-bc3a-feface71af75", "type": "concept", "title": "localization"}, {"id": "18ad3c68-1ed5-462a-bc6c-6f5be3eea15a", "type": "concept", "title": "vernacular graphics"}, {"id": "a9c6d399-8163-4bc3-a995-062c7d49b2ff", "type": "concept", "title": "bilingual layout"}, {"id": "039f735c-0355-4b81-bef3-56db04abaab2", "type": "concept", "title": "script politics"}, {"id": "4dd83f70-6eee-4740-8215-5edcd9e94c9a", "type": "concept", "title": "cultural specificity"}], "description": "Students learn how language, script systems, local materials, and audiences complicate universal design claims."}]}, {"id": "63699456-adbc-422c-b515-f91d519e61d4", "type": "topic", "title": "Design, Politics, Protest, and Social Change", "description": "Graphic design has shaped public opinion, social movements, state power, protest culture, and civic communication.", "children": [{"id": "6109a86f-f50d-451e-bf5c-7af2137d7bc2", "type": "subtopic", "title": "Propaganda and public persuasion", "children": [{"id": "3520a87f-0c79-43b5-88f2-2304ab93d936", "type": "concept", "title": "propaganda poster"}, {"id": "719d672e-d6ba-4f6c-91a5-c92e6131e883", "type": "concept", "title": "war bond"}, {"id": "291d587e-9044-4a90-9c1e-a1618178d479", "type": "concept", "title": "public health campaign"}, {"id": "c80875e0-a596-4351-9cac-8169b885cc14", "type": "concept", "title": "national symbol"}, {"id": "2cf48e06-1c19-46b1-88cd-575f5cd2e584", "type": "concept", "title": "rhetoric"}, {"id": "f1fef007-8187-4150-9b71-cb7544f2ee3f", "type": "concept", "title": "mass persuasion"}], "description": "Students study how states, parties, and institutions use graphic form to simplify messages and mobilize publics."}, {"id": "f6497042-1272-4d85-b568-c6bc6636d876", "type": "subtopic", "title": "Protest graphics and activist design", "children": [{"id": "aff1e652-ac6d-479f-b496-a9e33ac5882e", "type": "concept", "title": "screenprint poster"}, {"id": "b669ff1d-243f-447f-b145-d3c7ca382736", "type": "concept", "title": "zine"}, {"id": "d3baac4f-68de-4c6f-be05-83ce2c14640d", "type": "concept", "title": "movement identity"}, {"id": "248abcd0-f96d-4657-969e-2afa8cfb96db", "type": "concept", "title": "DIY production"}, {"id": "c3338550-031b-4f88-9a6f-556ffa191420", "type": "concept", "title": "solidarity graphics"}, {"id": "9fe8f95f-5543-49af-90b8-653394fe560c", "type": "concept", "title": "viral graphic"}], "description": "This subtopic examines posters, zines, banners, social media graphics, and identity systems for social movements."}, {"id": "6b5a4182-6abd-4114-ae2f-9870c6f16277", "type": "subtopic", "title": "Ethics of persuasive design", "children": [{"id": "3ab0461b-0881-40a0-94a3-332f1cdfcbf8", "type": "concept", "title": "visual rhetoric"}, {"id": "d2076dac-4207-4a64-b4b5-a83fc1d933db", "type": "concept", "title": "misinformation"}, {"id": "e2c48bf0-bed7-4313-beb2-a4f75aeef0fb", "type": "concept", "title": "stereotype"}, {"id": "b195541f-c401-4a50-9b93-876e7f5f3ffd", "type": "concept", "title": "accessibility"}, {"id": "377f4b33-8319-4bb1-a6ad-696f1f4b2e51", "type": "concept", "title": "civic design"}, {"id": "c66f63be-c92a-4d5c-9d78-2bc0cf2731eb", "type": "concept", "title": "ethical communication"}], "description": "Students evaluate the line between persuasion, manipulation, simplification, and public responsibility."}]}, {"id": "b23e1010-a753-4851-8c0e-9b92051eaed9", "type": "topic", "title": "Contemporary Design: Platforms, AI, Sustainability, and Ethics", "description": "Contemporary design history is still being made. This unit situates current practice in relation to platforms, ecological crisis, data, artificial intelligence, and labor.", "children": [{"id": "01132ca3-97e5-49b5-90ac-407119c17a52", "type": "subtopic", "title": "Platform visual culture", "children": [{"id": "3187d3f1-0ae6-445d-a5b5-7ca0f28b908c", "type": "concept", "title": "platform aesthetic"}, {"id": "3c92e03d-af1c-4d44-95d3-3af021d69608", "type": "concept", "title": "creator economy"}, {"id": "79063c0b-e249-49f9-82a5-65f28a86cbeb", "type": "concept", "title": "engagement metric"}, {"id": "d64b06fd-e895-487a-9022-7ec0e06850eb", "type": "concept", "title": "template"}, {"id": "ca91ec44-bdd1-4d53-99d6-28409d9541c8", "type": "concept", "title": "brand social"}, {"id": "dfa801a5-8c4c-450c-8791-299d7dfa2fa8", "type": "concept", "title": "content system"}], "description": "Students analyze how apps, feeds, metrics, and templates shape visual style and design labor."}, {"id": "e1651d61-e566-43fd-86eb-83407377ad8f", "type": "subtopic", "title": "Sustainable and responsible design", "children": [{"id": "e440ecf5-f5ef-41c0-9738-e26c16fee26a", "type": "concept", "title": "sustainable design"}, {"id": "4345463d-7b81-44c3-a6f0-ac4b491e9a1e", "type": "concept", "title": "life cycle"}, {"id": "e8bf9513-c24d-4470-8b61-9f1c40e95d10", "type": "concept", "title": "paper sourcing"}, {"id": "f8a0dcf5-8a51-433b-9829-e0a3874cf542", "type": "concept", "title": "ink and substrate"}, {"id": "23d5a88e-1cbf-4e7e-9e45-9036f10591ad", "type": "concept", "title": "dematerialization"}, {"id": "ae164d3a-2774-4289-8d1b-d52665afbf11", "type": "concept", "title": "greenwashing"}], "description": "This subtopic connects historical production to environmental impact, material choices, repair, and reduced consumption."}, {"id": "61fc0cca-7312-467b-a1f9-4f90df44e342", "type": "subtopic", "title": "AI and design authorship", "children": [{"id": "020071e7-0431-4d3a-b68c-2aa26f40a537", "type": "concept", "title": "generative AI"}, {"id": "187e2212-9e1a-4718-9daa-232b60dc71a8", "type": "concept", "title": "training data"}, {"id": "2edb2cd4-b006-4bb7-a67a-bbe92918b295", "type": "concept", "title": "prompting"}, {"id": "accc7ade-c5bc-4e30-a643-1f6cc6518466", "type": "concept", "title": "authorship"}, {"id": "3bdeb3c2-4db4-42f2-a258-9a5d947afa02", "type": "concept", "title": "style extraction"}, {"id": "a5fde135-c094-4cbe-b90c-3a58bc9979dd", "type": "concept", "title": "labor displacement"}], "description": "Students consider how generative systems challenge authorship, labor, originality, attribution, and historical memory."}]}, {"id": "13c6b66b-7c09-4760-96cb-f704573e8067", "type": "topic", "title": "Designers, Studios, and Movements to Know", "description": "This unit builds a rigorous reference map of designers, studios, movements, institutions, and objects that recur across design-history scholarship.", "children": [{"id": "e9d39f58-00c4-45e7-95d2-d7f0689d7558", "type": "subtopic", "title": "Key designers and studios", "children": [{"id": "aee16e92-620b-44c4-b7e3-f3542ac1734b", "type": "concept", "title": "William Morris"}, {"id": "54d3417a-91b0-40c9-b544-1c83cc716208", "type": "concept", "title": "Herbert Bayer"}, {"id": "e538342e-ef7d-4099-80a7-e6a2f0b08fed", "type": "concept", "title": "Paul Rand"}, {"id": "e3b8195d-710b-4358-b541-c0efab4671b3", "type": "concept", "title": "Saul Bass"}, {"id": "c5aae792-f871-4160-834b-b7fb8532119a", "type": "concept", "title": "Muriel Cooper"}, {"id": "080b0c79-9194-4c84-b238-6d55c16ab11b", "type": "concept", "title": "Massimo Vignelli"}], "description": "Students learn major figures while also questioning why certain names become canonical."}, {"id": "ec5817d2-24a8-4b5b-90bf-b2926469a79d", "type": "subtopic", "title": "Movements and periodization", "children": [{"id": "86a7e3a5-5fa8-418b-838f-6bedf6232894", "type": "concept", "title": "Arts and Crafts"}, {"id": "da235554-b147-4388-a9a3-c19de27009fc", "type": "concept", "title": "Art Nouveau"}, {"id": "f9ca3279-85eb-4718-95e4-bf089d8a8f3d", "type": "concept", "title": "Constructivism"}, {"id": "8fa6279e-bff8-4640-8c6d-0fed13144fed", "type": "concept", "title": "Bauhaus"}, {"id": "02198e2b-94b4-4d72-afce-5358ac572c8a", "type": "concept", "title": "International Style"}, {"id": "32533035-b14b-4bf5-8c11-c6f87c95b2fe", "type": "concept", "title": "Postmodernism"}], "description": "This subtopic helps students organize historical periods without treating movements as isolated style labels."}, {"id": "be9e9d72-ee33-4833-b70e-8d61c02b77dc", "type": "subtopic", "title": "Counter-canons and rediscovery", "children": [{"id": "c3ea1123-7b64-4234-845b-cedb7416dd3c", "type": "concept", "title": "Sister Corita Kent"}, {"id": "d760110f-a720-4c09-9117-ad5037749abd", "type": "concept", "title": "Luba Lukova"}, {"id": "a1b09442-8c33-41ee-994b-c4bff9d5f42b", "type": "concept", "title": "Jacqueline Casey"}, {"id": "b77b6ea9-ba1c-444a-8d26-138d31e205e6", "type": "concept", "title": "Emory Douglas"}, {"id": "f98bc768-46ed-4809-a09a-639446961987", "type": "concept", "title": "collective practice"}, {"id": "0c5f6cf2-df67-4835-b0bc-698523853ce1", "type": "concept", "title": "anonymous designer"}], "description": "Students identify overlooked designers, collectives, local practices, and anonymous labor that complicate survey narratives."}]}, {"id": "3c8bb9b3-9de0-493b-a133-9a7fb3ea150d", "type": "topic", "title": "Archives, Museums, and Object-Based Research", "description": "Design history depends on collections and evidence. Students learn to use archives, museums, catalogs, and primary sources responsibly.", "children": [{"id": "018555ef-76da-4a03-b2ec-5944ab1f3032", "type": "subtopic", "title": "Working with design archives", "children": [{"id": "a9b452a2-7522-4817-a63b-ba700f523a05", "type": "concept", "title": "finding aid"}, {"id": "cb7731b7-ce0a-4f1d-a32f-6d460565eebf", "type": "concept", "title": "accession"}, {"id": "0d568d31-80ca-4fff-9eaf-7ca1512ab90c", "type": "concept", "title": "ephemera"}, {"id": "9517bd9b-fcbd-4209-8975-ce0560cf4b3b", "type": "concept", "title": "primary source"}, {"id": "8cdc240d-f778-44bc-af19-192200bb01eb", "type": "concept", "title": "metadata"}, {"id": "2d2a1bb3-612a-488f-999a-aae56f6db99b", "type": "concept", "title": "provenance"}], "description": "Students learn how to locate, describe, and interpret primary sources such as posters, specimens, manuals, sketches, and ephemera."}, {"id": "af56fff9-4340-4cb3-8e58-8e171241ff41", "type": "subtopic", "title": "Museum collections and exhibitions", "children": [{"id": "26496f69-8b99-4570-886e-8df15c733370", "type": "concept", "title": "curatorial frame"}, {"id": "57a5ab6a-d2e1-48e5-b5eb-62cfa94faf70", "type": "concept", "title": "object label"}, {"id": "cf790856-212f-442a-b647-5fb54f7b4a67", "type": "concept", "title": "exhibition design"}, {"id": "b2d9dc97-7f3a-48fa-be85-5e5e3e99d26c", "type": "concept", "title": "collection policy"}, {"id": "7792e83d-0c00-45e0-801a-2a3d0e74f111", "type": "concept", "title": "museum interpretation"}, {"id": "89d938da-2d69-453d-a311-440ec2f04276", "type": "concept", "title": "Cooper Hewitt"}], "description": "This subtopic examines how institutions classify, display, and narrate design objects."}, {"id": "0a44494d-579c-4048-8491-954c91fe6abd", "type": "subtopic", "title": "Digital collections and citation", "children": [{"id": "2d493bb8-32f6-4275-b2dd-e2a2b64228f5", "type": "concept", "title": "digital archive"}, {"id": "291619ad-fda4-4fad-8882-a1a510ed2f91", "type": "concept", "title": "image rights"}, {"id": "bba0a9c8-7081-4b91-afea-293a0252275c", "type": "concept", "title": "caption"}, {"id": "3a0dd5ef-401a-42d7-b646-809347d115eb", "type": "concept", "title": "citation"}, {"id": "a16794a8-d161-4781-9da4-aef4efeaf7aa", "type": "concept", "title": "IIIF"}, {"id": "b12bafaa-d06d-4939-b98b-79790525a4b7", "type": "concept", "title": "collection database"}], "description": "Students practice using online collections while documenting sources, rights, captions, and image context."}]}, {"id": "5d914d39-723f-402b-8fbc-363ab732f9bc", "type": "topic", "title": "Historical Writing, Visual Analysis, and Curatorial Practice", "description": "The course culminates in historical argument-making: students learn to write, curate, and present design history with evidence and visual precision.", "children": [{"id": "498bfdd8-1d78-42f2-8f68-10562ea004cd", "type": "subtopic", "title": "Design-history writing", "children": [{"id": "2a8f76db-42aa-4fed-beb3-d693608dde90", "type": "concept", "title": "thesis"}, {"id": "53e68b03-fc1c-43e5-9f27-ffd9ffb32624", "type": "concept", "title": "visual evidence"}, {"id": "cb7bcf49-b13a-4d57-bb17-d40f4a279453", "type": "concept", "title": "historical context"}, {"id": "48f6774e-522b-45fd-aba2-982325b5a5fb", "type": "concept", "title": "comparative analysis"}, {"id": "d291a1a0-70c6-4209-85d9-34b055a92d12", "type": "concept", "title": "period claim"}, {"id": "ff10bd8e-3e9f-46b8-8ba5-8ac6a75d82ee", "type": "concept", "title": "scholarly citation"}], "description": "Students learn to turn close looking and research into claims about form, context, technology, audience, and meaning."}, {"id": "0feeea8a-b1bd-4220-a358-b1a0df9c768c", "type": "subtopic", "title": "Case-study research", "children": [{"id": "10e8c794-fa96-406a-9354-9b8067abd159", "type": "concept", "title": "case study"}, {"id": "f285c10c-84c6-4f0d-a97d-fe0172263042", "type": "concept", "title": "research question"}, {"id": "94a58423-5601-49c9-a936-0eaacc7238a5", "type": "concept", "title": "object biography"}, {"id": "b72bded1-45ba-4648-aaed-2382c37aa7c5", "type": "concept", "title": "source triangulation"}, {"id": "c0455436-c35b-4dcf-9cdd-73b20a6ff4af", "type": "concept", "title": "annotated bibliography"}, {"id": "eafc6e35-bb69-4a6f-9889-a60101de53b3", "type": "concept", "title": "image analysis"}], "description": "This subtopic develops a focused research project around one artifact, designer, movement, publication, identity system, or archive."}, {"id": "95f77692-fc40-4402-848f-7692e4effe1c", "type": "subtopic", "title": "Curatorial presentation", "children": [{"id": "198667ce-5df8-4c3c-b5c8-27602e09293d", "type": "concept", "title": "curatorial statement"}, {"id": "48e5cc48-e26e-44c2-b9e3-901047803c11", "type": "concept", "title": "wall label"}, {"id": "4309ffca-b659-4787-ad7c-0d88e01a29cc", "type": "concept", "title": "timeline"}, {"id": "3f514d0a-b484-4464-a669-79ad0c89ce12", "type": "concept", "title": "object grouping"}, {"id": "8ecdefa0-0065-483f-b671-78bf088b8b1c", "type": "concept", "title": "public interpretation"}, {"id": "9a6f5411-641b-4915-977a-adde06373abf", "type": "concept", "title": "presentation critique"}], "description": "Students translate research into exhibition, presentation, or digital-story formats that teach others how to see design historically."}]}], "dbBacked": true}$dhisjson$::jsonb,
