update public.learning_paths
set
  title = 'Design History',
  goal = 'Design History',
  summary = 'Design History surveys the development of graphic design and visual communication from early writing and print culture through industrial production, reform movements, modernism, Swiss style, corporate identity, postmodernism, digital media, global design histories, contemporary platforms, and ethical design practice. Students learn to analyze artifacts, read visual form historically, question design canons, use archives and museum collections, and write critical design-history arguments.',
  data = $dhisjson${"slug": "design-history", "title": "Design History", "description": "Design History surveys the development of graphic design and visual communication from early writing and print culture through industrial production, reform movements, modernism, Swiss style, corporate identity, postmodernism, digital media, global design histories, contemporary platforms, and ethical design practice. Students learn to analyze artifacts, read visual form historically, question design canons, use archives and museum collections, and write critical design-history arguments.", "topics": [{"id": "b749db31-89b8-4389-9525-5aedc705fa44", "type": "topic", "title": "Design History as Visual Culture and Method", "description": "This opening unit frames design history as the study of visual communication, technology, labor, markets, institutions, and culture rather than a simple parade of styles.", "children": [{"id": "a78be4ae-3807-4720-bf51-56801d88d836", "type": "subtopic", "title": "What counts as design history", "children": [{"id": "1e15bbc3-a4de-4171-8d23-ddf1176ef179", "type": "concept", "title": "artifact"}, {"id": "b542474e-7f4d-4411-9200-54c4e2a5297b", "type": "concept", "title": "visual culture"}, {"id": "09fab5bf-8758-45e7-b55c-955a031302dc", "type": "concept", "title": "graphic design"}, {"id": "caf6cf3d-a62b-4cbd-9428-18b8a76b3821", "type": "concept", "title": "communication design"}, {"id": "31865fa9-cb80-46af-947d-540535998791", "type": "concept", "title": "vernacular design"}, {"id": "496274d5-721a-4882-93f6-3b2c2b0d45e3", "type": "concept", "title": "material culture"}], "description": "Students learn how posters, books, signs, interfaces, packaging, typefaces, corporate identity, and vernacular graphics become historical evidence."}, {"id": "96cae6ac-d0f1-412b-9a2e-be8691a51374", "type": "subtopic", "title": "Methods of visual analysis", "children": [{"id": "aca408a1-8209-45cc-bfb4-c2838ae5349e", "type": "concept", "title": "formal analysis"}, {"id": "34a09fd3-aca3-4ad6-9194-b14a0ae6916d", "type": "concept", "title": "iconography"}, {"id": "ed8e1982-ce1c-40e4-bbca-482609c72627", "type": "concept", "title": "composition"}, {"id": "dec4dafe-9104-4e51-afa9-c59bacbc5c3a", "type": "concept", "title": "typographic analysis"}, {"id": "e7c89e99-fa10-448b-93f7-acfe9c2dd1f4", "type": "concept", "title": "semiotics"}, {"id": "43aae45e-b0e7-451b-9f51-ca0c0179397b", "type": "concept", "title": "contextual reading"}], "description": "This subtopic introduces close looking and historical interpretation so students can connect form to context."}, {"id": "02c1a806-d1b3-495a-81a4-d6359d7bcaab", "type": "subtopic", "title": "Canons, archives, and missing histories", "children": [{"id": "f96fc276-89ac-4e77-b287-c3e00ed14a4c", "type": "concept", "title": "canon formation"}, {"id": "85036372-6dc9-4ca8-9a1a-ee7059d47716", "type": "concept", "title": "archive bias"}, {"id": "f35dbe13-841d-4281-9f26-c86252d4cf1a", "type": "concept", "title": "anonymous labor"}, {"id": "57abe375-835a-4be4-90ce-f2700566adb5", "type": "concept", "title": "women designers"}, {"id": "3b3a9309-7e41-4d8c-bf95-8f906476154d", "type": "concept", "title": "racial exclusion"}, {"id": "24f136f1-e8e8-451f-be64-389d2eb84972", "type": "concept", "title": "decolonial method"}], "description": "Students question whose work is preserved, taught, collected, and excluded from dominant design-history narratives."}]}, {"id": "68b57b31-4abf-4b2f-ab1a-c36d15017e7b", "type": "topic", "title": "Origins of Graphic Communication and Early Print", "description": "This unit studies the long prehistory of graphic design, from writing systems and manuscripts to movable type and early print culture.", "children": [{"id": "a7e84fc2-d4fc-4fe2-9e17-557b8d98d30d", "type": "subtopic", "title": "Writing systems and manuscript cultures", "children": [{"id": "7738bec0-d2c0-47cc-8954-360b0f2774a7", "type": "concept", "title": "cuneiform"}, {"id": "dbb56975-ed44-4d22-b14c-f527a88b99ef", "type": "concept", "title": "hieroglyphics"}, {"id": "e73c194c-6bad-42b4-a89e-cbdd4d5123ff", "type": "concept", "title": "calligraphy"}, {"id": "470ec618-c841-4a67-91fe-1fb1b46c1fb9", "type": "concept", "title": "illuminated manuscript"}, {"id": "5647a282-737d-4081-ab8c-a89cab65f7f2", "type": "concept", "title": "scribal labor"}, {"id": "79c13f31-86fa-4c70-89ef-d0e23aada4f7", "type": "concept", "title": "page architecture"}], "description": "Students trace how visual communication emerged through scripts, symbols, religious texts, and administrative records."}, {"id": "e232e3d3-f4f0-45dc-801c-3887ae9166b2", "type": "subtopic", "title": "Movable type and print revolution", "children": [{"id": "a937e349-963a-4cdb-95fa-eed8897178ce", "type": "concept", "title": "Gutenberg"}, {"id": "04c6be5e-0ef4-418e-96c7-4f857b1ebcbf", "type": "concept", "title": "movable type"}, {"id": "904d2512-fb1f-495f-ade9-867c26f14dd3", "type": "concept", "title": "incunabula"}, {"id": "dd724741-61d3-4689-b01d-9e6057790a41", "type": "concept", "title": "woodcut"}, {"id": "2e538487-cf7f-4c61-b974-3662f00aa298", "type": "concept", "title": "engraving"}, {"id": "c3c80c75-8f18-489e-9435-a82c53dd2a5f", "type": "concept", "title": "printer-publisher"}], "description": "This subtopic explains how print changed reproduction, authorship, standardization, literacy, and public communication."}, {"id": "3dba2021-b4d6-4a9e-b5e1-de487ea68e40", "type": "subtopic", "title": "Early type and book design", "children": [{"id": "4ae1be16-d19b-41df-9a54-735955953515", "type": "concept", "title": "roman type"}, {"id": "e580156d-c259-4c10-9d2f-fa31615bfac9", "type": "concept", "title": "blackletter"}, {"id": "de3d3cf3-2d97-40fb-a0be-80972d19810c", "type": "concept", "title": "humanist type"}, {"id": "b07a8d2f-7c33-4392-a5b8-4fc84db66d37", "type": "concept", "title": "title page"}, {"id": "6ea72b9e-26f9-47eb-b937-7ee265ba5787", "type": "concept", "title": "margins"}, {"id": "0c68a9e1-66c4-4b07-bfda-10a92b9e8c74", "type": "concept", "title": "colophon"}], "description": "Students learn the historical roots of type classification, page proportion, ornament, and reader experience."}]}, {"id": "dba41f25-3aa1-4423-ace9-a6135ddeef95", "type": "topic", "title": "Industrial Revolution, Mass Media, and Advertising", "description": "Industrialization transformed design through mechanized printing, mass audiences, urban posters, packaging, newspapers, and consumer culture.", "children": [{"id": "70b67330-7e78-4c8c-a5ca-8cbbef7b259b", "type": "subtopic", "title": "Mechanized printing and reproduction", "children": [{"id": "cb480251-8ca0-4b3c-9d1f-82a4d716f8cf", "type": "concept", "title": "lithography"}, {"id": "e183b138-5759-44d3-898e-1d3332240198", "type": "concept", "title": "chromolithography"}, {"id": "7ac8d966-4305-4de1-8fc3-dae363f855f5", "type": "concept", "title": "steam press"}, {"id": "f2ee21d5-1b16-4e64-9784-41a5a88d5095", "type": "concept", "title": "halftone"}, {"id": "6234e3ee-7a91-43dc-b817-642eb6f4d22c", "type": "concept", "title": "typefoundry"}, {"id": "8a25ccf1-36e5-4ba8-81d7-29310cda0afe", "type": "concept", "title": "mechanical reproduction"}], "description": "Students connect new technologies to faster production, larger editions, color printing, and changing design labor."}, {"id": "35ce2585-7a86-4388-8a4a-0c595049d5bf", "type": "subtopic", "title": "Advertising and consumer culture", "children": [{"id": "ed1c2ce8-c84a-4fce-b538-83a78ff4a4b0", "type": "concept", "title": "display type"}, {"id": "5565d33a-35a7-409f-829c-d4e12b62b8f1", "type": "concept", "title": "trade card"}, {"id": "6988ac3c-98bc-42c1-b612-ab32d49db16f", "type": "concept", "title": "poster culture"}, {"id": "27cd49bc-10fa-4e12-bbc2-cb407f7cde83", "type": "concept", "title": "packaging"}, {"id": "99906f91-f4c5-436c-a734-0b92dafc99df", "type": "concept", "title": "brand mark"}, {"id": "dae7aa74-3207-4e76-bd83-ce5dce184ef7", "type": "concept", "title": "department store"}], "description": "This subtopic examines how brands, posters, catalogs, and packaging reshaped public space and desire."}, {"id": "1536ab16-b235-4c2b-a280-4cbfc0b3bd02", "type": "subtopic", "title": "Information, newspapers, and public graphics", "children": [{"id": "108bb9a2-89cd-4e1d-9d77-c1390cbf7b2b", "type": "concept", "title": "newspaper layout"}, {"id": "467f7c1c-eae1-435b-ba93-90577e74d31a", "type": "concept", "title": "headline hierarchy"}, {"id": "2445a16f-646a-4fe5-bdc5-1b978af8c907", "type": "concept", "title": "caption"}, {"id": "67caf09d-2af5-4b0f-96a7-754b1441d6eb", "type": "concept", "title": "infographic precursor"}, {"id": "83a27754-06b4-4732-b7b5-c242f2e9eb83", "type": "concept", "title": "public notice"}, {"id": "08247ca2-92b0-42f0-b8e5-67c0c8624cfb", "type": "concept", "title": "railway timetable"}], "description": "Students study how mass media required hierarchy, grids, illustration, captions, and repeatable editorial systems."}]}, {"id": "ba37750c-a09c-42a7-a1f0-c311262c21d5", "type": "topic", "title": "Arts and Crafts, Art Nouveau, and Design Reform", "description": "This unit examines late nineteenth-century responses to industrial production, including craft revival, aesthetic reform, and organic graphic styles.", "children": [{"id": "9ad2b922-4c0f-42e4-8ccb-dbb61c6f3f19", "type": "subtopic", "title": "Arts and Crafts movement", "children": [{"id": "77c6f5a2-c9d9-4056-bbe6-4960093db2e5", "type": "concept", "title": "William Morris"}, {"id": "d3f9351a-de5a-447a-bfa9-e5d84924bbd0", "type": "concept", "title": "Kelmscott Press"}, {"id": "04f1904d-0aa5-452e-8e68-a07aa199b08f", "type": "concept", "title": "craft revival"}, {"id": "7d1bbef7-c010-4b79-af93-5cc2161d88af", "type": "concept", "title": "ornament"}, {"id": "8a0ed53b-e5fd-4ff3-9292-48d077fc55c9", "type": "concept", "title": "medievalism"}, {"id": "5f7711b3-ee7b-472e-ae94-d43f9a43ff00", "type": "concept", "title": "anti-industrial critique"}], "description": "Students learn how William Morris and related reformers linked design quality to labor, morality, and industrial critique."}, {"id": "b0bc8485-a6f3-429f-9329-e5181d2b79f7", "type": "subtopic", "title": "Art Nouveau and the modern poster", "children": [{"id": "cfc0b51c-2e90-4c15-b825-74874f1bf0b8", "type": "concept", "title": "Jules Cheret"}, {"id": "4e7c6d9f-5e01-4848-8482-adf5a5f123db", "type": "concept", "title": "Alphonse Mucha"}, {"id": "24f5df8b-b5c0-4fa9-98bd-71a8eccff0bd", "type": "concept", "title": "Henri de Toulouse-Lautrec"}, {"id": "3d76effb-6e27-44d4-a935-c213559f7416", "type": "concept", "title": "flat color"}, {"id": "cae8ff3c-6623-4cd0-bd8c-4acb5bfb668a", "type": "concept", "title": "whiplash line"}, {"id": "8086dec6-a422-4eb3-b3c5-d6eb8a74f6d9", "type": "concept", "title": "lithographic poster"}], "description": "This subtopic studies flowing line, flat color, sensual ornament, and the rise of designer-authored posters."}, {"id": "8cae468d-e8d6-4fa6-9651-0009bbe7bf8e", "type": "subtopic", "title": "Design reform and applied arts", "children": [{"id": "6e21bacb-a699-4050-b06e-4390e8ab85c8", "type": "concept", "title": "design reform"}, {"id": "e26ff375-8277-4a96-a1fa-345733183de3", "type": "concept", "title": "applied arts"}, {"id": "3074ae8b-ffe5-48d2-8afc-7fee625b707d", "type": "concept", "title": "Werkbund"}, {"id": "45c61531-6ab6-43fa-947d-9feb1e22b8af", "type": "concept", "title": "ornament debate"}, {"id": "c7863019-040a-40a9-9bca-8e0cb3d620a0", "type": "concept", "title": "total work of art"}, {"id": "1a9d22b4-2cfd-41c0-abb1-10cf6a8eff1d", "type": "concept", "title": "craft versus industry"}], "description": "Students connect reform movements to education, craft guilds, exhibitions, and the later emergence of modern design schools."}]}, {"id": "1938c190-befd-40c6-9ffd-b7cce601400c", "type": "topic", "title": "Modernism: Futurism, Constructivism, De Stijl, and Bauhaus", "description": "Modernist design sought new visual languages for industrial society, abstraction, political transformation, and universal communication.", "children": [{"id": "da27aab9-791c-437a-a987-e6542ca4ecc0", "type": "subtopic", "title": "Avant-garde typography and montage", "children": [{"id": "52ca6178-60f7-4acc-a1fe-a73eaa4a20f5", "type": "concept", "title": "Futurism"}, {"id": "25bca5f2-3889-4158-86fb-c3e61d8e8804", "type": "concept", "title": "Dada"}, {"id": "ec7b4983-4310-4472-aeeb-5df832bbc07c", "type": "concept", "title": "photomontage"}, {"id": "e53f2a20-45ab-4f76-8d99-0f816bad1e54", "type": "concept", "title": "asymmetry"}, {"id": "d67f642e-1f0f-4e4c-bf56-82c6736ec2cc", "type": "concept", "title": "dynamic typography"}, {"id": "6ac2ecbb-2192-4a50-9965-1d6f5dcf288d", "type": "concept", "title": "El Lissitzky"}], "description": "Students study how Futurists, Dadaists, and Constructivists broke classical page order to express speed, rupture, and politics."}, {"id": "aaefccdb-07ca-4a61-9079-e42c344538a8", "type": "subtopic", "title": "De Stijl and geometric abstraction", "children": [{"id": "b70e9926-a3bf-463b-ab85-b565e7d6dd39", "type": "concept", "title": "De Stijl"}, {"id": "00006097-ea5c-4458-a721-62554c068480", "type": "concept", "title": "Piet Mondrian"}, {"id": "4d557466-8b7c-4a1a-8e4b-813d32888252", "type": "concept", "title": "Theo van Doesburg"}, {"id": "03e38310-36b1-4435-84ec-d1acdb0834a3", "type": "concept", "title": "grid"}, {"id": "d8b55c86-9e65-4413-b40c-08ad5dbe9e76", "type": "concept", "title": "primary color"}, {"id": "03b83971-5bb9-446c-95dd-0cd65153b794", "type": "concept", "title": "geometric reduction"}], "description": "This subtopic explores reduction, grids, primary colors, and the search for universal visual order."}, {"id": "dabba2be-9e69-4345-bcea-57020059293c", "type": "subtopic", "title": "Bauhaus pedagogy and modern design education", "children": [{"id": "be36b563-6f42-4cdc-aecc-54c0665cd7ef", "type": "concept", "title": "Bauhaus"}, {"id": "47302437-0576-4af5-a03a-87476157ec91", "type": "concept", "title": "Vorkurs"}, {"id": "0adae1ee-5265-48d4-8531-eced2bc5b145", "type": "concept", "title": "Herbert Bayer"}, {"id": "4c9e3dfc-e6ce-4c53-91c4-d3ec6e082518", "type": "concept", "title": "László Moholy-Nagy"}, {"id": "dde44e51-9e58-490f-bf6e-1b1dd855ec68", "type": "concept", "title": "workshop model"}, {"id": "a1480349-406a-49a0-9bc7-6157ec43393e", "type": "concept", "title": "form follows function"}], "description": "Students learn how the Bauhaus linked foundation studies, workshop practice, typography, industry, and design theory."}]}, {"id": "53e6ccdf-87ec-4acd-9ff6-0f10bdd71792", "type": "topic", "title": "Swiss International Style and Corporate Modernism", "description": "This unit covers rational grids, sans serif typography, objectivity, and the postwar corporate identity systems that shaped twentieth-century visual communication.", "children": [{"id": "cd61bc06-16d5-4b9b-b81a-c1f1bb3ce244", "type": "subtopic", "title": "International Typographic Style", "children": [{"id": "3b9d0422-0803-4946-a613-08428f81bb26", "type": "concept", "title": "Josef Muller-Brockmann"}, {"id": "7d37ae50-7101-4090-a24c-b05908bb5c75", "type": "concept", "title": "Armin Hofmann"}, {"id": "6fb73182-9b68-4136-8fe4-9bf74da615a3", "type": "concept", "title": "grid system"}, {"id": "8c2ba8e4-b196-4950-9837-023c2d22cddb", "type": "concept", "title": "asymmetrical layout"}, {"id": "95bb412c-da51-42a4-8838-27cad1b28d02", "type": "concept", "title": "Akzidenz-Grotesk"}, {"id": "dc4a1175-fd2b-40f9-a072-fdc63b49022a", "type": "concept", "title": "photographic objectivity"}], "description": "Students learn the formal language of Swiss design and its promise of clarity, neutrality, and systematic order."}, {"id": "f044e144-dbd3-4616-bfa4-bf2171931d90", "type": "subtopic", "title": "Corporate identity systems", "children": [{"id": "7d5d793e-01a8-4ccd-ac7b-10db79f52346", "type": "concept", "title": "Paul Rand"}, {"id": "30027e7b-0765-48fb-b2cd-a72cc7d03343", "type": "concept", "title": "Chermayeff & Geismar"}, {"id": "6d77887d-2076-46c9-98e5-f9a3b74c1d13", "type": "concept", "title": "identity manual"}, {"id": "2458508c-d567-4dde-98ec-39236b63b4e2", "type": "concept", "title": "logo"}, {"id": "942ad94f-8ae1-4f8f-887c-69025bc7f465", "type": "concept", "title": "system standards"}, {"id": "88b7fa04-41c0-48d4-8f75-3d4fd713bb5f", "type": "concept", "title": "brand consistency"}], "description": "This subtopic studies how institutions used marks, manuals, color, type, and repeatable standards to manage public presence."}, {"id": "73a172d6-0be6-4e92-8de9-700f089ce94c", "type": "subtopic", "title": "Critiques of neutrality", "children": [{"id": "66f73613-b548-40b1-b8cb-d422c5dbbf1e", "type": "concept", "title": "neutrality myth"}, {"id": "e74a8b52-dd55-40bd-92d2-75408260fb20", "type": "concept", "title": "corporate voice"}, {"id": "bfa1dd44-ba6a-4bd7-b333-5d695665aedf", "type": "concept", "title": "institutional authority"}, {"id": "4d8c63dc-e20b-4ac2-9125-bcec5cb15eea", "type": "concept", "title": "legibility politics"}, {"id": "8ab6313f-87dc-4355-ac77-f14d15bfdd36", "type": "concept", "title": "modernist exclusion"}, {"id": "9062d9b6-f724-4bb3-ad5e-5c49567cd78c", "type": "concept", "title": "global export"}], "description": "Students question whether modernist clarity is ever culturally neutral and examine how power can hide inside universal style."}]}, {"id": "87c873c3-0fc5-46b0-9c81-48f29d19de96", "type": "topic", "title": "Typography, Letterforms, and Publication Histories", "description": "Typography has its own histories of tools, technologies, classification, distribution, and cultural meaning. This unit makes type central to design history.", "children": [{"id": "b6e20a01-5f8e-427a-8bc1-6a02b02fd6f6", "type": "subtopic", "title": "Type classification and historical form", "children": [{"id": "b104e2e1-99b2-498c-b6e6-7f4b148fae11", "type": "concept", "title": "old style"}, {"id": "d4c63a52-ae48-49b7-9a92-5567888c6fab", "type": "concept", "title": "transitional"}, {"id": "e9b02448-5cb0-4703-bb84-5594a290e4cd", "type": "concept", "title": "modern"}, {"id": "2a921fd8-f42e-4c95-823d-13059e982b7d", "type": "concept", "title": "slab serif"}, {"id": "aa3da45d-69c6-44a9-ae52-3d8c507b36d1", "type": "concept", "title": "grotesque"}, {"id": "6718df2f-5f74-460b-814e-4b7dc570880c", "type": "concept", "title": "humanist sans"}], "description": "Students learn how typefaces carry traces of tools, periods, and reading technologies."}, {"id": "327d8240-43b4-4eaf-827f-7a04c8c1660a", "type": "subtopic", "title": "Letterpress, phototype, and digital type", "children": [{"id": "4d4bc912-8454-42a9-a4cc-e35af3af5643", "type": "concept", "title": "letterpress"}, {"id": "71001466-df99-4a96-9238-fe10f4a585dd", "type": "concept", "title": "Linotype"}, {"id": "fdb1b566-5cc5-4153-846a-81889d3e6bde", "type": "concept", "title": "Monotype"}, {"id": "628779a9-cc6e-407c-be55-6e647d3d310d", "type": "concept", "title": "phototypesetting"}, {"id": "67b731e6-611e-47a2-92da-d83cb77a32bc", "type": "concept", "title": "PostScript"}, {"id": "8966d286-0d34-4305-847b-337d05e605d8", "type": "concept", "title": "OpenType"}], "description": "This subtopic follows changes in production from metal type to phototypesetting to font software."}, {"id": "f96163e7-2d10-4d8d-93c6-767f5ea9220d", "type": "subtopic", "title": "Typographic culture and archives", "children": [{"id": "4fa7faf7-8a7e-45a2-b877-2f7acf9dc591", "type": "concept", "title": "type specimen"}, {"id": "f6b19075-8454-4d14-a341-fbe3f244799b", "type": "concept", "title": "foundry"}, {"id": "d8ea6d61-8b31-427f-8e76-462e6ff23bb1", "type": "concept", "title": "revival"}, {"id": "ce46b9e2-32e7-4e2d-82e5-44318418284c", "type": "concept", "title": "Letterform Archive"}, {"id": "7d2050c2-a9ed-4bf0-bf1b-e1e0ff253e39", "type": "concept", "title": "vernacular lettering"}, {"id": "36b7e662-b8b4-4438-8d5e-0f3a8bf882ce", "type": "concept", "title": "font licensing"}], "description": "Students study specimens, foundry histories, revivals, and letterform collections as evidence."}]}, {"id": "b5bbd016-fc5d-482f-9365-e39e5b544fab", "type": "topic", "title": "Identity, Branding, and Design Systems in History", "description": "Branding has a long history that connects marks, commerce, institutions, standardization, and public trust.", "children": [{"id": "83825466-179b-438c-b25f-5ad2dfa73d1f", "type": "subtopic", "title": "Marks, symbols, and trademarks", "children": [{"id": "1ffff46d-6b55-44b4-910c-a7916c870ca9", "type": "concept", "title": "maker mark"}, {"id": "73529f91-730e-4e01-b339-a20864487e3c", "type": "concept", "title": "trademark"}, {"id": "3caedc9a-f550-4297-9c75-4890a0c25cd1", "type": "concept", "title": "symbol"}, {"id": "126f337b-767f-4bc8-bfdb-689106b39698", "type": "concept", "title": "monogram"}, {"id": "8c0a381e-f442-4d98-bb92-2938a8304b99", "type": "concept", "title": "seal"}, {"id": "a3fb52f4-a542-49c3-9cad-2e23de47921f", "type": "concept", "title": "brand recognition"}], "description": "Students connect early maker marks and trademarks to modern logo systems and intellectual property."}, {"id": "cca3924e-ca17-4587-8627-cca8b4e5d484", "type": "subtopic", "title": "System design and standards", "children": [{"id": "b6f07db7-8de3-49aa-8823-08cf7c9dcc31", "type": "concept", "title": "standards manual"}, {"id": "59b8d8d0-d3d9-4863-acf8-514d5b242e1e", "type": "concept", "title": "visual identity"}, {"id": "3ffb2bb7-12b2-47f5-9657-e06c2f5a70ec", "type": "concept", "title": "wayfinding"}, {"id": "5a5f06f6-cc91-4ef1-a9a4-e9a1b063056e", "type": "concept", "title": "supergraphics"}, {"id": "27017911-6cef-457e-8d84-11f85e992614", "type": "concept", "title": "application system"}, {"id": "fbdedaf1-b891-44b3-8051-a1ed72da61b9", "type": "concept", "title": "design guidelines"}], "description": "This subtopic examines how identity systems coordinate type, color, layout, imagery, signage, and applications."}, {"id": "7ba1ef65-e966-4b9c-b547-fb7aceb99a43", "type": "subtopic", "title": "Branding as cultural narrative", "children": [{"id": "a5a4