shing"}, {"id": "3cbbdae7-cda4-4f74-adc1-7540e72c56b5", "type": "concept", "title": "PageMaker"}, {"id": "86eba3fc-8852-4166-b696-4a485644435c", "type": "concept", "title": "QuarkXPress"}, {"id": "4862060a-92ef-40d0-a418-e35ce73ee215", "type": "concept", "title": "Photoshop"}, {"id": "8d3979b0-bebb-49f4-9531-b6918fa378c6", "type": "concept", "title": "digital prepress"}], "description": "Students learn how personal computers, page-layout software, and digital type changed who could make and distribute design."}, {"id": "e6597421-7e72-456f-b855-c76203f33bf5", "type": "subtopic", "title": "Web and interface histories", "children": [{"id": "0d689c38-6b23-4a95-8a3f-fffb3260a927", "type": "concept", "title": "HTML"}, {"id": "4e2235fa-78a5-4449-bccd-5d227bbbfe55", "type": "concept", "title": "browser"}, {"id": "2446ae64-1055-44f4-8e95-5a6040c2cb12", "type": "concept", "title": "GUI"}, {"id": "bf7209c9-1a56-4fe3-86e7-cc405d2b15d6", "type": "concept", "title": "pixel grid"}, {"id": "2642fe50-df95-4bf3-931e-8515d8841e66", "type": "concept", "title": "responsive design"}, {"id": "c4fa6e05-8dc4-4ff0-bdeb-7db25c9dc716", "type": "concept", "title": "interaction pattern"}], "description": "This subtopic connects graphic design to early websites, screens, interaction patterns, and interface standards."}, {"id": "07295c04-3d46-4254-9992-67fde8776d2b", "type": "subtopic", "title": "Platforms, templates, and automation", "children": [{"id": "1212d038-a33b-4a3c-8596-9de6abcd53b8", "type": "concept", "title": "template culture"}, {"id": "f5fd2192-4c16-4eb3-91dc-6e0d7f36948c", "type": "concept", "title": "social media graphics"}, {"id": "b5a2cb4b-10af-419b-855f-f29cf9e01184", "type": "concept", "title": "platform constraint"}, {"id": "c695f89b-5f3c-4abf-8b7b-576210e3885a", "type": "concept", "title": "algorithmic feed"}, {"id": "ce4cdbcb-bd0b-4993-89b3-3e5fc9fa02ae", "type": "concept", "title": "design system"}, {"id": "a4df12cc-10d7-4f9d-8397-9921d1bfba84", "type": "concept", "title": "generative tool"}], "description": "Students analyze contemporary design production through templates, social media systems, no-code tools, and algorithmic distribution."}]}, {"id": "2c07f430-0e71-49ca-adcd-4d5ee13179fd", "type": "topic", "title": "Global and Decolonial Design Histories", "description": "Design history must move beyond a narrow Euro-American canon and study design across regions, languages, scripts, colonial histories, and local visual systems.", "children": [{"id": "2aae5d8e-757e-4fa4-9c7a-f100f0114fc3", "type": "subtopic", "title": "Non-Western modernisms", "children": [{"id": "1f6bf009-0c08-4473-b2da-4065da383397", "type": "concept", "title": "Latin American modernism"}, {"id": "007f79bb-2934-43e2-a75d-1c71e4331f31", "type": "concept", "title": "Japanese graphic design"}, {"id": "e10ebefe-1b5f-4633-b171-d9c144be6f31", "type": "concept", "title": "Indian print culture"}, {"id": "5aa778f1-fe3e-447c-9d32-230756a9e2ed", "type": "concept", "title": "African poster traditions"}, {"id": "0e213406-40bf-4d39-87e3-d28eb2a4e026", "type": "concept", "title": "Arabic typography"}, {"id": "6eff128b-5758-44cf-bdca-921ed65a30d9", "type": "concept", "title": "postcolonial modernity"}], "description": "Students examine modern design in Latin America, East Asia, South Asia, Africa, and the Middle East on its own terms."}, {"id": "78f7d1f4-0123-46e9-979d-8b98c27ba053", "type": "subtopic", "title": "Colonialism, nationalism, and design", "children": [{"id": "758f6725-cde1-4aac-9de4-e7829d1d926f", "type": "concept", "title": "colonial exhibition"}, {"id": "6db179e7-c3fa-4d28-9d77-d495e1b47917", "type": "concept", "title": "propaganda"}, {"id": "3326e64c-7df4-46be-a5d6-d48853f34691", "type": "concept", "title": "national identity"}, {"id": "0cf62d80-b60a-4029-bbfe-9f123c884d60", "type": "concept", "title": "anti-colonial graphics"}, {"id": "c4724bb7-5050-47f5-80e1-78c68061ab8e", "type": "concept", "title": "public information"}, {"id": "6eefff8e-bd5b-40f1-98e2-4c89734fd85a", "type": "concept", "title": "state design"}], "description": "This subtopic connects design to empire, independence movements, public campaigns, and national identity."}, {"id": "c92e47e9-08b9-4d91-94ff-bba4430bebff", "type": "subtopic", "title": "Translation, script, and locality", "children": [{"id": "6881c469-0726-4984-b3e2-98f54991a9bf", "type": "concept", "title": "multiscript typography"}, {"id": "805da5c4-9b2e-45d8-bc3a-feface71af75", "type": "concept", "title": "localization"}, {"id": "18ad3c68-1ed5-462a-bc6c-6f5be3eea15a", "type": "concept", "title": "vernacular graphics"}, {"id": "a9c6d399-8163-4bc3-a995-062c7d49b2ff", "type": "concept", "title": "bilingual layout"}, {"id": "039f735c-0355-4b81-bef3-56db04abaab2", "type": "concept", "title": "script politics"}, {"id": "4dd83f70-6eee-4740-8215-5edcd9e94c9a", "type": "concept", "title": "cultural specificity"}], "description": "Students learn how language, script systems, local materials, and audiences complicate universal design claims."}]}, {"id": "63699456-adbc-422c-b515-f91d519e61d4", "type": "topic", "title": "Design, Politics, Protest, and Social Change", "description": "Graphic design has shaped public opinion, social movements, state power, protest culture, and civic communication.", "children": [{"id": "6109a86f-f50d-451e-bf5c-7af2137d7bc2", "type": "subtopic", "title": "Propaganda and public persuasion", "children": [{"id": "3520a87f-0c79-43b5-88f2-2304ab93d936", "type": "concept", "title": "propaganda poster"}, {"id": "719d672e-d6ba-4f6c-91a5-c92e6131e883", "type": "concept", "title": "war bond"}, {"id": "291d587e-9044-4a90-9c1e-a1618178d479", "type": "concept", "title": "public health campaign"}, {"id": "c80875e0-a596-4351-9cac-8169b885cc14", "type": "concept", "title": "national symbol"}, {"id": "2cf48e06-1c19-46b1-88cd-575f5cd2e584", "type": "concept", "title": "rhetoric"}, {"id": "f1fef007-8187-4150-9b71-cb7544f2ee3f", "type": "concept", "title": "mass persuasion"}], "description": "Students study how states, parties, and institutions use graphic form to simplify messages and mobilize publics."}, {"id": "f6497042-1272-4d85-b568-c6bc6636d876", "type": "subtopic", "title": "Protest graphics and activist design", "children": [{"id": "aff1e652-ac6d-479f-b496-a9e33ac5882e", "type": "concept", "title": "screenprint poster"}, {"id": "b669ff1d-243f-447f-b145-d3c7ca382736", "type": "concept", "title": "zine"}, {"id": "d3baac4f-68de-4c6f-be05-83ce2c14640d", "type": "concept", "title": "movement identity"}, {"id": "248abcd0-f96d-4657-969e-2afa8cfb96db", "type": "concept", "title": "DIY production"}, {"id": "c3338550-031b-4f88-9a6f-556ffa191420", "type": "concept", "title": "solidarity graphics"}, {"id": "9fe8f95f-5543-49af-90b8-653394fe560c", "type": "concept", "title": "viral graphic"}], "description": "This subtopic examines posters, zines, banners, social media graphics, and identity systems for social movements."}, {"id": "6b5a4182-6abd-4114-ae2f-9870c6f16277", "type": "subtopic", "title": "Ethics of persuasive design", "children": [{"id": "3ab0461b-0881-40a0-94a3-332f1cdfcbf8", "type": "concept", "title": "visual rhetoric"}, {"id": "d2076dac-4207-4a64-b4b5-a83fc1d933db", "type": "concept", "title": "misinformation"}, {"id": "e2c48bf0-bed7-4313-beb2-a4f75aeef0fb", "type": "concept", "title": "stereotype"}, {"id": "b195541f-c401-4a50-9b93-876e7f5f3ffd", "type": "concept", "title": "accessibility"}, {"id": "377f4b33-8319-4bb1-a6ad-696f1f4b2e51", "type": "concept", "title": "civic design"}, {"id": "c66f63be-c92a-4d5c-9d78-2bc0cf2731eb", "type": "concept", "title": "ethical communication"}], "description": "Students evaluate the line between persuasion, manipulation, simplification, and public responsibility."}]}, {"id": "b23e1010-a753-4851-8c0e-9b92051eaed9", "type": "topic", "title": "Contemporary Design: Platforms, AI, Sustainability, and Ethics", "description": "Contemporary design history is still being made. This unit situates current practice in relation to platforms, ecological crisis, data, artificial intelligence, and labor.", "children": [{"id": "01132ca3-97e5-49b5-90ac-407119c17a52", "type": "subtopic", "title": "Platform visual culture", "children": [{"id": "3187d3f1-0ae6-445d-a5b5-7ca0f28b908c", "type": "concept", "title": "platform aesthetic"}, {"id": "3c92e03d-af1c-4d44-95d3-3af021d69608", "type": "concept", "title": "creator economy"}, {"id": "79063c0b-e249-49f9-82a5-65f28a86cbeb", "type": "concept", "title": "engagement metric"}, {"id": "d64b06fd-e895-487a-9022-7ec0e06850eb", "type": "concept", "title": "template"}, {"id": "ca91ec44-bdd1-4d53-99d6-28409d9541c8", "type": "concept", "title": "brand social"}, {"id": "dfa801a5-8c4c-450c-8791-299d7dfa2fa8", "type": "concept", "title": "content system"}], "description": "Students analyze how apps, feeds, metrics, and templates shape visual style and design labor."}, {"id": "e1651d61-e566-43fd-86eb-83407377ad8f", "type": "subtopic", "title": "Sustainable and responsible design", "children": [{"id": "e440ecf5-f5ef-41c0-9738-e26c16fee26a", "type": "concept", "title": "sustainable design"}, {"id": "4345463d-7b81-44c3-a6f0-ac4b491e9a1e", "type": "concept", "title": "life cycle"}, {"id": "e8bf9513-c24d-4470-8b61-9f1c40e95d10", "type": "concept", "title": "paper sourcing"}, {"id": "f8a0dcf5-8a51-433b-9829-e0a3874cf542", "type": "concept", "title": "ink and substrate"}, {"id": "23d5a88e-1cbf-4e7e-9e45-9036f10591ad", "type": "concept", "title": "dematerialization"}, {"id": "ae164d3a-2774-4289-8d1b-d52665afbf11", "type": "concept", "title": "greenwashing"}], "description": "This subtopic connects historical production to environmental impact, material choices, repair, and reduced consumption."}, {"id": "61fc0cca-7312-467b-a1f9-4f90df44e342", "type": "subtopic", "title": "AI and design authorship", "children": [{"id": "020071e7-0431-4d3a-b68c-2aa26f40a537", "type": "concept", "title": "generative AI"}, {"id": "187e2212-9e1a-4718-9daa-232b60dc71a8", "type": "concept", 